def extract_contact_field_from_search_result(contact_record: dict, requested_field: str) -> dict:
    if not contact_record:
        return {'answer_value': '', 'answer_field': '', 'source_person_id': '', 'abstain_reason': 'missing_contact_record'}
    if not requested_field or requested_field not in contact_record:
        return {'answer_value': '', 'answer_field': requested_field, 'source_person_id': contact_record.get('person_id', ''), 'abstain_reason': 'missing_requested_field'}
    answer_value = contact_record[requested_field]
    return {'answer_value': answer_value, 'answer_field': requested_field, 'source_person_id': contact_record.get('person_id', ''), 'abstain_reason': ''}

def extract_service_answer_field(service_payload: dict) -> dict:
    """
    Extract a single scalar answer from a visible service_payload dict.
    Returns a dict with keys: answer_value (str), answer_kind (str), answer_unit (str), abstain_reason (str).
    Abstains with abstain_reason 'no_supported_answer_field' when no supported scalar field is present.
    """
    # Safe input guard
    if not isinstance(service_payload, dict):
        return {"answer_value": "", "answer_kind": "", "answer_unit": "", "abstain_reason": "no_supported_answer_field"}

    # Priority-ordered candidate keys (first match wins)
    candidates = [
        ("phone_number", "phone_number"),
        ("address", "address"),
        ("current_temperature", "current_temperature"),
        ("temperature", "temperature"),
        ("distance", "distance"),
        ("converted_amount", "converted_amount"),
        ("convertedAmount", "convertedAmount"),
        ("amount", "amount"),
        ("value", "value"),
    ]

    # Unit-like keys to check (prefer more specific keys first)
    unit_keys = [
        "temperature_unit", "temperatureUnit", "distance_unit", "distanceUnit",
        "converted_amount_unit", "convertedAmount_unit", "amount_unit",
        "unit", "currency", "currency_unit"
    ]

    for payload_key, kind in candidates:
        if payload_key in service_payload:
            val = service_payload[payload_key]
            # Accept scalar types only
            if isinstance(val, (str, int, float, bool)):
                # Convert numeric/bool to string for consistent answer_value
                answer_value = str(val)
                # Find any unit-like sibling
                answer_unit = ""
                for uk in unit_keys:
                    if uk in service_payload:
                        uk_val = service_payload[uk]
                        if isinstance(uk_val, str):
                            answer_unit = uk_val
                            break
                return {
                    "answer_value": answer_value,
                    "answer_kind": kind,
                    "answer_unit": answer_unit,
                    "abstain_reason": ""
                }
            else:
                # Found a supported key but the value isn't a scalar -> abstain
                return {"answer_value": "", "answer_kind": "", "answer_unit": "", "abstain_reason": "no_supported_answer_field"}

    # No supported keys found -> abstain
    return {"answer_value": "", "answer_kind": "", "answer_unit": "", "abstain_reason": "no_supported_answer_field"}

def plan_contact_lookup_query(contact_name: str, phone_number: str, relationship: str, requested_field: str) -> dict:
    search_contacts_kwargs = {}
    should_call_search_contacts = False
    abstain_reason = ''

    if not requested_field:
        abstain_reason = 'requested_field is blank'
    else:
        if contact_name:
            search_contacts_kwargs['name'] = contact_name.strip()
            should_call_search_contacts = True
        if phone_number:
            search_contacts_kwargs['phone_number'] = phone_number.strip()
            should_call_search_contacts = True
        if relationship:
            search_contacts_kwargs['relationship'] = relationship.strip()
            should_call_search_contacts = True

        if not search_contacts_kwargs:
            abstain_reason = 'missing_lookup_constraint'

    return {
        'should_call_search_contacts': should_call_search_contacts,
        'search_contacts_kwargs': search_contacts_kwargs,
        'answer_field': requested_field,
        'abstain_reason': abstain_reason
    }

def plan_contact_search_from_scalar_constraint(constraint_field: str, constraint_value: str) -> dict:
    normalized_constraint_value = constraint_value.strip()
    if constraint_field == 'phone_number':
        normalized_constraint_value = normalized_constraint_value.replace(' ', '').replace('-', '').replace('(', '').replace(')', '')
        if normalized_constraint_value.startswith('+'):
            return_value = normalized_constraint_value
        else:
            if len(normalized_constraint_value) == 11 and normalized_constraint_value[0] == '1':
                return_value = '+' + normalized_constraint_value
            elif len(normalized_constraint_value) == 10:
                return_value = '+1' + normalized_constraint_value
            else:
                return_value = '+' + normalized_constraint_value
        return {
            'should_call_search': True,
            'search_tool_name': 'search_contacts',
            'search_kwargs': {'phone_number': return_value},
            'normalized_constraint_field': 'phone_number',
            'normalized_constraint_value': return_value,
            'abstain_reason': ''
        }
    elif constraint_field == 'name' or constraint_field == 'relationship':
        return {
            'should_call_search': True,
            'search_tool_name': 'search_contacts',
            'search_kwargs': {constraint_field: normalized_constraint_value},
            'normalized_constraint_field': constraint_field,
            'normalized_constraint_value': normalized_constraint_value,
            'abstain_reason': ''
        }
    else:
        return {
            'should_call_search': False,
            'search_tool_name': '',
            'search_kwargs': {},
            'normalized_constraint_field': '',
            'normalized_constraint_value': '',
            'abstain_reason': 'missing_contact_constraint'
        }

def prepare_side_effect_args_from_selected_record(selected_record: dict = None, action_type: str = "", updates: dict = None, user_intent: str = "") -> dict:
    """
    Prepare downstream tool name and kwargs for an already-selected visible record.

    Returns a dict with keys: downstream_tool_name (str), downstream_tool_kwargs (dict), should_call_tool (bool), abstain_reason (str).
    """
    sel = selected_record or {}
    upd = updates or {}
    act = (action_type or "").strip().lower()

    # Safe empty return template
    empty_result = {
        "downstream_tool_name": "",
        "downstream_tool_kwargs": {},
        "should_call_tool": False,
        "abstain_reason": ""
    }

    if not sel:
        return {**empty_result, "abstain_reason": "missing_selected_record"}

    # Helper: check for at least one non-empty update field
    def has_concrete_updates(u: dict) -> bool:
        if not isinstance(u, dict):
            return False
        for k, v in u.items():
            if v is None:
                continue
            if isinstance(v, str) and v.strip() == "":
                continue
            return True
        return False

    # Phone normalization per E.164 guidance in the spec
    def normalize_phone(raw: str) -> str:
        if raw is None:
            return ""
        s = str(raw).strip()
        if s == "":
            return ""
        leading_plus = s.startswith("+")
        # Remove everything except digits
        digits = "".join(ch for ch in s if ch.isdigit())
        if leading_plus:
            # preserve leading + and stripped digits
            if digits == "":
                return ""
            return "+" + digits
        # No leading plus: use rules
        if len(digits) == 11 and digits[0] == "1":
            return "+" + digits
        if len(digits) == 10:
            return "+1" + digits
        # fallback: return the stripped digits (no +)
        return digits

    # Normalize action aliases to canonical actions
    canonical = ""
    if act in {"remove", "delete"}:
        # choose contact vs reminder by available ids
        if "person_id" in sel:
            canonical = "remove_contact"
        elif "reminder_id" in sel:
            canonical = "remove_reminder"
    elif act in {"modify", "update", "change"}:
        if "person_id" in sel:
            canonical = "modify_contact"
        elif "reminder_id" in sel:
            canonical = "modify_reminder"
    elif act in {"send", "send_message", "message", "send_sms"}:
        canonical = "send_message"
    elif act in {"add_reminder", "create_reminder", "set_reminder"}:
        canonical = "add_reminder"
    else:
        # accept direct canonical names as well
        if act in {"modify_contact", "remove_contact", "modify_reminder", "remove_reminder", "send_message", "add_reminder"}:
            canonical = act

    if canonical == "":
        return {**empty_result, "abstain_reason": "unsupported_action"}

    # Prepare per-action kwargs
    if canonical == "modify_contact":
        if "person_id" not in sel:
            return {**empty_result, "abstain_reason": "missing_required_id"}
        if not has_concrete_updates(upd):
            return {**empty_result, "abstain_reason": "empty_updates_for_modify"}
        kwargs = {"person_id": sel.get("person_id")}
        # Merge updates (preserve provided casing and spacing for names)
        for k, v in upd.items():
            kwargs[k] = v
        return {"downstream_tool_name": "modify_contact", "downstream_tool_kwargs": kwargs, "should_call_tool": True, "abstain_reason": ""}

    if canonical == "remove_contact":
        if "person_id" not in sel:
            return {**empty_result, "abstain_reason": "missing_required_id"}
        return {"downstream_tool_name": "remove_contact", "downstream_tool_kwargs": {"person_id": sel.get("person_id")}, "should_call_tool": True, "abstain_reason": ""}

    if canonical == "modify_reminder":
        if "reminder_id" not in sel:
            return {**empty_result, "abstain_reason": "missing_required_id"}
        if not has_concrete_updates(upd):
            return {**empty_result, "abstain_reason": "empty_updates_for_modify"}
        kwargs = {"reminder_id": sel.get("reminder_id")}
        for k, v in upd.items():
            kwargs[k] = v
        return {"downstream_tool_name": "modify_reminder", "downstream_tool_kwargs": kwargs, "should_call_tool": True, "abstain_reason": ""}

    if canonical == "remove_reminder":
        if "reminder_id" not in sel:
            return {**empty_result, "abstain_reason": "missing_required_id"}
        return {"downstream_tool_name": "remove_reminder", "downstream_tool_kwargs": {"reminder_id": sel.get("reminder_id")}, "should_call_tool": True, "abstain_reason": ""}

    if canonical == "add_reminder":
        # For adding a reminder, require at least one concrete field (time or content)
        if not has_concrete_updates(upd):
            return {**empty_result, "abstain_reason": "insufficient_information"}
        kwargs = {}
        # copy any explicit fields
        for k, v in upd.items():
            kwargs[k] = v
        return {"downstream_tool_name": "add_reminder", "downstream_tool_kwargs": kwargs, "should_call_tool": True, "abstain_reason": ""}

    if canonical == "send_message":
        # Determine recipient: prefer recipient_person_id, then person_id, then recipient_id, then phone fields
        recipient_person = None
        for key in ("recipient_person_id", "person_id", "recipient_id", "sender_person_id", "recipient_person"):
            if key in sel and sel.get(key):
                recipient_person = sel.get(key)
                break
        phone_source = None
        for pkey in ("phone_number", "phone", "mobile", "phone_number_e164"):
            if pkey in sel and sel.get(pkey):
                phone_source = sel.get(pkey)
                break
        # Message content can come from updates keys 'content','message','text'
        content = None
        for ck in ("content", "message", "text", "body"):
            if ck in upd and upd.get(ck):
                content = upd.get(ck)
                break
        # If no explicit content in updates, attempt to extract from user_intent heuristics (only when clear 'send' intent)
        if not content:
            if isinstance(user_intent, str) and user_intent.strip().lower().startswith("send"):
                # weak heuristic: not sufficient to auto-fill content
                content = None
        # Construct kwargs
        kwargs = {}
        if recipient_person:
            kwargs["recipient_person_id"] = recipient_person
        elif phone_source:
            norm = normalize_phone(phone_source)
            if norm:
                kwargs["phone_number"] = norm
        # Allow explicit phone in updates to override
        if "phone_number" in upd and upd.get("phone_number"):
            kwargs["phone_number"] = normalize_phone(upd.get("phone_number"))
        if "recipient_person_id" in upd and upd.get("recipient_person_id"):
            kwargs["recipient_person_id"] = upd.get("recipient_person_id")
        if content:
            kwargs["content"] = content
        elif "content" in upd and upd.get("content"):
            kwargs["content"] = upd.get("content")

        # Validate we have recipient and content
        has_recipient = ("recipient_person_id" in kwargs) or ("phone_number" in kwargs)
        has_content = ("content" in kwargs)
        if not has_recipient or not has_content:
            return {**empty_result, "abstain_reason": "insufficient_information"}
        return {"downstream_tool_name": "send_message", "downstream_tool_kwargs": kwargs, "should_call_tool": True, "abstain_reason": ""}

    # Fallback (should not be reached)
    return {**empty_result, "abstain_reason": "unsupported_action"}

def resolve_search_window_or_bounds(
    current_timestamp: float,
    phrase: str,
    target_domain: str,
    timestamp_intent: str,
    direction: str,
    content_keyword: str = "",
    lookback_days: int = 0,
    timezone_offset: float = 0.0,
) -> dict:
    min_timestamp = 315529200.0
    now = float(current_timestamp)
    if now <= 0:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "missing_current_timestamp",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    domain = str(target_domain or "").strip().lower()
    if domain == "message":
        tool_name = "search_messages"
    elif domain == "reminder":
        tool_name = "search_reminder"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_target_domain",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    intent = str(timestamp_intent or "").strip().lower()
    if domain == "message":
        lower_key = "creation_timestamp_lowerbound"
        upper_key = "creation_timestamp_upperbound"
    elif intent == "creation":
        lower_key = "creation_timestamp_lowerbound"
        upper_key = "creation_timestamp_upperbound"
    elif intent == "reminder":
        lower_key = "reminder_timestamp_lowerbound"
        upper_key = "reminder_timestamp_upperbound"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_timestamp_intent",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    normalized_direction = str(direction or "").strip().lower()
    normalized_phrase = str(phrase or "").strip().lower()
    if not normalized_direction:
        if normalized_phrase in ("yesterday", "today", "later today", "later_today", "upcoming", "recent", "latest", "oldest"):
            normalized_direction = normalized_phrase.replace(" ", "_")
        else:
            return {
                "target_tool_name": "",
                "search_kwargs": {},
                "should_call_search": False,
                "abstain_reason": "ambiguous_phrase",
                "interpretation": "",
                "bounds_source": "abstain",
            }
    offset_seconds = float(timezone_offset) * 3600.0
    local_now = now + offset_seconds
    local_day_start = float(int(local_now // 86400.0) * 86400.0)
    day_start = local_day_start - offset_seconds
    next_day_start = day_start + 86400.0
    kwargs = {}
    interpretation = normalized_direction
    bounds_source = "resolved_direction"
    if normalized_direction == "yesterday":
        kwargs[lower_key] = max(min_timestamp, day_start - 86400.0)
        kwargs[upper_key] = max(min_timestamp, day_start - 1.0)
    elif normalized_direction == "today":
        kwargs[lower_key] = max(min_timestamp, day_start)
        kwargs[upper_key] = max(min_timestamp, next_day_start - 1.0)
    elif normalized_direction == "later_today":
        kwargs[lower_key] = max(min_timestamp, now)
        kwargs[upper_key] = max(min_timestamp, next_day_start - 1.0)
    elif normalized_direction == "upcoming":
        kwargs[lower_key] = max(min_timestamp, now)
    elif normalized_direction == "recent":
        days = int(lookback_days)
        if days <= 0:
            days = 7
        kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
        kwargs[upper_key] = max(min_timestamp, now)
    elif normalized_direction in ("latest", "oldest"):
        if domain == "message":
            kwargs[upper_key] = max(min_timestamp, now)
        else:
            days = int(lookback_days)
            if days <= 0:
                days = 3650
            kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
            kwargs[upper_key] = max(min_timestamp, now)
    elif normalized_direction == "custom":
        days = int(lookback_days)
        if days <= 0:
            return {
                "target_tool_name": "",
                "search_kwargs": {},
                "should_call_search": False,
                "abstain_reason": "custom_window_requires_positive_lookback_days",
                "interpretation": "",
                "bounds_source": "abstain",
            }
        kwargs[lower_key] = max(min_timestamp, now - days * 86400.0)
        kwargs[upper_key] = max(min_timestamp, now)
        interpretation = "custom_lookback"
    else:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "unsupported_direction",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    if str(content_keyword or "").strip():
        kwargs["content"] = str(content_keyword)
    if not kwargs:
        return {
            "target_tool_name": "",
            "search_kwargs": {},
            "should_call_search": False,
            "abstain_reason": "no_search_criteria_prepared",
            "interpretation": "",
            "bounds_source": "abstain",
        }
    return {
        "target_tool_name": tool_name,
        "search_kwargs": kwargs,
        "should_call_search": True,
        "abstain_reason": "",
        "interpretation": interpretation,
        "bounds_source": bounds_source,
    }

def select_record_by_timestamp_extreme(
    records,
    timestamp_field,
    mode,
    tie_break_fields=None,
    required_filters=None,
    allow_missing_timestamp=False,
):
    if mode not in ("latest", "oldest"):
        return {
            "selected_record": None,
            "selected_index": None,
            "selected_timestamp": None,
            "should_use_selected_record": False,
            "abstain_reason": "invalid_mode",
            "selection_reason": "",
        }
    best_idx = None
    best_record = None
    best_ts = None
    for i, record in enumerate(records or []):
        if not isinstance(record, dict):
            continue
        if required_filters:
            filter_match = True
            for _fk, _fv in required_filters.items():
                if record.get(_fk) != _fv:
                    filter_match = False
                    break
            if not filter_match:
                continue
        ts_raw = record.get(timestamp_field)
        if ts_raw is None:
            continue
        if not isinstance(ts_raw, (int, float)):
            continue
        ts_val = float(ts_raw)
        if best_ts is None:
            best_idx = i
            best_record = record
            best_ts = ts_val
        elif mode == "latest" and ts_val > best_ts:
            best_idx = i
            best_record = record
            best_ts = ts_val
        elif mode == "oldest" and ts_val < best_ts:
            best_idx = i
            best_record = record
            best_ts = ts_val
    if best_record is None:
        return {
            "selected_record": None,
            "selected_index": None,
            "selected_timestamp": None,
            "should_use_selected_record": False,
            "abstain_reason": "no_valid_timestamped_records",
            "selection_reason": "",
        }
    return {
        "selected_record": best_record,
        "selected_index": best_idx,
        "selected_timestamp": best_ts,
        "should_use_selected_record": True,
        "abstain_reason": "",
        "selection_reason": "selected_" + mode + "_by_" + str(timestamp_field),
    }
